[Expected Approach 2] Using Hashing - O(n) time and O(1) spaceWe can use an hash map or dictionary to store the values of Roman symbols. And to solve the problem, we have to iterate through the string and for each symbol, check if the current value is less than the next value. If so, subtract the current value from the next value and add the result to the total. Otherwise, add the current value to the total.
            C++

    #include <iostream>
#include <unordered_map>
using namespace std;

int romanToInteger(string &s) {
    unordered_map<char, int> romanMap = {{'I', 1}, 
                                         {'V', 5}, 
                                         {'X', 10}, 
                                         {'L', 50},
                                         {'C', 100}, 
                                         {'D', 500}, 
                                         {'M', 1000}};

    int res = 0;
    for (int i = 0; i < s.length(); i++) {

        // if the current value is less than the next value, 
        // subtract current from next and add to res
        if (i + 1 < s.length() && romanMap[s[i]] < romanMap[s[i + 1]]) {
            res += romanMap[s[i + 1]] - romanMap[s[i]];

            // skip the next symbol
            i++;
        }
        else {

            // otherwise, add the current value to res
            res += romanMap[s[i]];
        }
    }

    return res;
}

int main() {

    string s = "IX";
    cout << romanToInteger(s) << endl;
    return 0;
}


